package com.dreamcore.workspace;
import com.dreamcore.workspace.identity.BackupObservationReader;
import java.nio.file.*;import java.nio.file.attribute.PosixFilePermissions;import java.time.Instant;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
class BackupObservationReaderTest {
 @TempDir Path root;Path file;Instant now=Instant.parse("2026-10-04T12:00:00Z");JsonMapper json=new JsonMapper();
 @BeforeEach void setup(){file=root.resolve("observation.json");}
 Map<String,Object> event(String command,String state){var m=new LinkedHashMap<String,Object>();m.put("id",UUID.randomUUID().toString());m.put("command",command);m.put("state",state);m.put("startedAt",now.minusSeconds(20).toString());m.put("finishedAt",state.equals("RUNNING")?null:now.minusSeconds(10).toString());m.put("snapshot",null);return m;}
 void write(List<?> events,Instant updated)throws Exception{Files.writeString(file,json.writeValueAsString(Map.of("format","dreamcore-backup-observation-v1","updatedAt",updated.toString(),"events",events)));Files.setPosixFilePermissions(file,PosixFilePermissions.fromString("rw-------"));}
 BackupObservationReader.Observation read(){return new BackupObservationReader(file.toString(),900).read(now);}
 @Test void absentAndUnreadableAreUnknownNotZero()throws Exception{assertEquals("NOT_CONFIGURED",new BackupObservationReader("",900).read(now).state());assertEquals("UNAVAILABLE",read().state());write(List.of(),now);assertEquals("FRESH",read().state());Files.setPosixFilePermissions(file,PosixFilePermissions.fromString("rw-r--r--"));assertEquals("UNAVAILABLE",read().state());}
 @Test void stagesRemainIndependentAndSnapshotIsOnlyAllowlistedMetadata()throws Exception{var e=event("RESTORE","SUCCEEDED");e.put("snapshot",Map.of("id",UUID.randomUUID().toString(),"createdAt",now.minusSeconds(500).toString(),"expiresAt",now.plusSeconds(500).toString(),"bytes",100,"files",3,"tables",12));write(List.of(e),now);var r=read();assertEquals("FRESH",r.state());assertEquals("RESTORE",r.events().getFirst().command());assertEquals(100,r.events().getFirst().snapshot().bytes());assertEquals(1,r.events().size());}
 @Test void oldRunningRecordBecomesUnknownEvenIfAnotherCommandRecentlyWrote()throws Exception{var old=event("CREATE","RUNNING");old.put("startedAt",now.minusSeconds(1000).toString());write(List.of(old,event("VERIFY","SUCCEEDED")),now);var r=read();assertEquals("FRESH",r.state());assertEquals("UNKNOWN",r.events().getLast().state());assertNull(r.events().getLast().finishedAt());write(List.of(old),now.minusSeconds(950));assertEquals("STALE",read().state());}
 @Test void rejectsSecretFieldsInvalidEnumsAndChronology()throws Exception{for(String key:List.of("path","credentials","error","content")){var e=event("VERIFY","FAILED");e.put(key,"private");write(List.of(e),now);assertEquals("UNAVAILABLE",read().state());assertTrue(read().events().isEmpty());}
  var e=event("RESTORE","SUCCEEDED");e.put("finishedAt",null);write(List.of(e),now);assertEquals("UNAVAILABLE",read().state());write(List.of(event("SECRET","SUCCEEDED")),now);assertEquals("UNAVAILABLE",read().state());write(List.of(event("VERIFY","FAILED")),now.plusSeconds(60));assertEquals("UNAVAILABLE",read().state());
  e=event("VERIFY","SUCCEEDED");e.put("snapshot",Map.of("id",UUID.randomUUID().toString(),"createdAt",now.toString(),"expiresAt",now.plusSeconds(60).toString(),"bytes",-1,"files",1,"tables",1));write(List.of(e),now);assertEquals("UNAVAILABLE",read().state());
 }
 @Test void duplicateOversizedLinkedAndMalformedRecordsAreRejected()throws Exception{var e=event("VERIFY","SUCCEEDED");write(List.of(e,e),now);assertEquals("UNAVAILABLE",read().state());write(Collections.nCopies(41,e),now);assertEquals("UNAVAILABLE",read().state());Files.writeString(file,"x".repeat(65537));assertEquals("UNAVAILABLE",read().state());write(List.of(e),now);String raw=Files.readString(file);Files.writeString(file,raw.replace("\"events\":", "\"events\":[],\"events\":"));assertEquals("UNAVAILABLE",read().state());Files.delete(file);Path target=root.resolve("private");Files.writeString(target,raw);Files.createSymbolicLink(file,target);assertEquals("UNAVAILABLE",read().state());Files.delete(file);Files.createLink(file,target);assertEquals("UNAVAILABLE",read().state());}
}
